$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$creds=json_decode(file_get_contents($argv[2]),true);$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function check(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}
function test(string $n,callable $f):void{global $r;try{$f();$r['passed']++;$r['cases'][$n]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$n]=get_class($e).':'.$e->getMessage();}}
function denied(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException){return;}throw new RuntimeException('Expected rejection');}
function req():string{return bin2hex(random_bytes(16));}
function principal(array $m,string $username,string $password):StaffSessionIdentity{global $db;$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$native=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($username,$password,'synthetic-seating');check($native!==null);$session=[];StaffAccountService::bind($session,$native);$session['_merchant_login_outlet']=$m['loginOutlet'];return new StaffSessionIdentity($db,static fn()=>$session,getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));}
$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$pa=principal($a,$a['username'],$creds['owner_a_password']);$pb=principal($b,$b['username'],$creds['owner_b_password']);$now=time();$svc=new Seating($db,$pa,static fn()=>$now);$other=new Seating($db,$pb);$call=fn($op,$d,$id=null)=>$svc->act($a['merchant'],$a['outlet'],$id??req(),$op,$d);$load=fn()=>$svc->load($a['merchant'],$a['outlet']);
if(($argv[3]??'')==='worker'){try{$svc->act($a['merchant'],$a['outlet'],$argv[4],'transition',['reservation'=>$argv[5],'version'=>'1','status'=>'CONFIRMED']);echo 'CONFIRMED';exit(0);}catch(DomainException){echo 'CONFLICT';exit(0);}}
$find=fn($kind,$id)=>array_values(array_filter($load()[$kind],fn($v)=>($v[$kind==='tables'?'table_id':'reservation_id'])===$id))[0];$floors=[];$tables=[];$booking=null;$staff=[];
test('025 migration applied and replay is empty',function()use($db){check(qualifiedMigrationSequence($db));check((new MigrationRunner($db))->apply(dirname(__DIR__,2).'/database/migrations')===[]);});
test('UTC and DST date interpretation rejects ambiguous and nonexistent times',function(){check(Seating::localInstant('2026-11-19T12:00','Asia/Kolkata')===Seating::localInstant('2026-11-19T06:30','UTC'));denied(fn()=>Seating::localInstant('2026-03-08T02:30','America/New_York'));denied(fn()=>Seating::localInstant('2026-11-01T01:30','America/New_York'));denied(fn()=>Seating::localInstant('2026-02-30T12:00','UTC'));});
test('Two floors four tables and persisted configuration',function()use($call,$load,&$floors,&$tables){foreach(['Ground Floor','First Floor']as $name)$floors[]=$call('floor',['id'=>'','version'=>'0','name'=>$name,'active'=>'1'])['result']['floor'];foreach($floors as $i=>$f)foreach([2,6]as $capacity)$tables[]=$call('table',['id'=>'','version'=>'0','floor'=>$f['floor_id'],'name'=>($i?'F':'G').$capacity,'capacity'=>(string)$capacity,'type'=>'standard','active'=>'1','notes'=>'Synthetic table'])['result']['table'];check(count($load()['tables'])===4);});
test('Strict capacities fields and configuration version conflicts',function()use($call,$tables){$t=$tables[0];$d=['id'=>$t['table_id'],'version'=>(string)$t['version'],'floor'=>$t['floor_id'],'name'=>$t['name'],'capacity'=>'0','type'=>'standard','active'=>'1','notes'=>''];denied(fn()=>$call('table',$d));$d['capacity']='2';$call('table',$d);denied(fn()=>$call('table',$d));$d['version']='2';$d['script']='bad';denied(fn()=>$call('table',$d));});
test('Timezone save preserves UTC and rejects stale booking timezone',function()use($call,$load,$tables,$now){$call('timezone',['timezone'=>'Asia/Kolkata','version'=>(string)$load()['settings']['version']]);denied(fn()=>$call('reserve',['table'=>$tables[1]['table_id'],'guest'=>'Stale zone','party'=>'2','start'=>gmdate('Y-m-d\TH:i',$now+600),'minutes'=>'60','notes'=>'','timezone_version'=>'1']));});
$reserve=function(string $table,string $name,int $offset=600,string $party='2',?string $request=null)use($call,$load,$now){$s=$load();return $call('reserve',['table'=>$table,'guest'=>$name,'party'=>$party,'start'=>Seating::local($now+$offset,$s['settings']['timezone_name'],'Y-m-d\TH:i'),'minutes'=>'60','notes'=>'Synthetic guest','timezone_version'=>(string)$s['settings']['version']],$request);};
test('Idempotent request creation and conflicting reuse',function()use($reserve,$tables,$call,$load,&$booking){$request=req();$first=$reserve($tables[1]['table_id'],'Demo Guest',600,'2',$request);$booking=$first['result']['reservation'];check($reserve($tables[1]['table_id'],'Demo Guest',600,'2',$request)['duplicate']);denied(fn()=>$reserve($tables[1]['table_id'],'Changed',600,'2',$request));check(count($load()['reservations'])===1);});
test('Confirmation capacity interval conflicts and adjacent slots',function()use($reserve,$tables,$call,$find,&$booking){denied(fn()=>$reserve($tables[0]['table_id'],'Too large',600,'3'));$call('transition',['reservation'=>$booking['reservation_id'],'version'=>'1','status'=>'CONFIRMED']);denied(fn()=>$reserve($tables[1]['table_id'],'Overlap'));$r=$reserve($tables[1]['table_id'],'Adjacent',4200)['result']['reservation'];$call('transition',['reservation'=>$r['reservation_id'],'version'=>'1','status'=>'CONFIRMED']);$call('transition',['reservation'=>$r['reservation_id'],'version'=>'2','status'=>'CANCELLED']);$booking=$find('reservations',$booking['reservation_id']);});
test('Real concurrent confirmations allow exactly one incompatible booking',function()use($reserve,$tables,$argv,$find,$call,&$r){$one=$reserve($tables[3]['table_id'],'Concurrent One',10800)['result']['reservation'];$two=$reserve($tables[3]['table_id'],'Concurrent Two',10800)['result']['reservation'];$children=[];foreach([$one,$two]as $v){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],'worker',req(),$v['reservation_id']],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);check(is_resource($p));fclose($pipes[0]);$children[]=[$p,$pipes];}$out=[];foreach($children as [$p,$pipes]){$o=stream_get_contents($pipes[1]);$e=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$r['workers'][]=['exit'=>$exit,'out'=>$o,'err'=>$e];check($exit===0);$out[]=$o;}sort($out);check($out===['CONFIRMED','CONFLICT']);foreach([$one,$two]as $v){$current=$find('reservations',$v['reservation_id']);$call('transition',['reservation'=>$v['reservation_id'],'version'=>(string)$current['version'],'status'=>'CANCELLED']);}});
test('Check-in seating transfer completion releases actual tables',function()use($call,$find,$tables,&$booking){$id=$booking['reservation_id'];denied(fn()=>$call('transition',['reservation'=>$id,'version'=>'2','status'=>'SEATED']));$call('checkin',['reservation'=>$id,'version'=>'2']);$call('transition',['reservation'=>$id,'version'=>'3','status'=>'SEATED']);check($find('tables',$tables[1]['table_id'])['operational_state']==='OCCUPIED');$call('assign',['reservation'=>$id,'version'=>'4','table'=>$tables[3]['table_id'],'reason'=>'Guest preference']);check($find('tables',$tables[1]['table_id'])['operational_state']==='AVAILABLE');check($find('tables',$tables[3]['table_id'])['current_reservation']===$id);$call('transition',['reservation'=>$id,'version'=>'5','status'=>'COMPLETED']);check($find('tables',$tables[3]['table_id'])['operational_state']==='AVAILABLE');denied(fn()=>$call('transition',['reservation'=>$id,'version'=>'6','status'=>'SEATED']));});
test('Operational holds walk-ins and out-of-service conflict rules',function()use($call,$find,$tables,$reserve){$id=$tables[0]['table_id'];$change=function($state,$party='1')use($call,$find,$id){$call('status',['table'=>$id,'version'=>(string)$find('tables',$id)['version'],'state'=>$state,'minutes'=>'60','party'=>$party,'reason'=>'Synthetic operation']);};$change('OCCUPIED','2');denied(fn()=>$reserve($id,'Blocked walk-in'));$change('AVAILABLE');$change('RESERVED');denied(fn()=>$reserve($id,'Held'));$change('AVAILABLE');$change('OUT_OF_SERVICE');denied(fn()=>$reserve($id,'Unavailable'));$change('AVAILABLE');});
test('No-show timing and table/floor deactivation preserve reservation history',function()use($reserve,$tables,$call,$floors,$find,$load,$db,$pa,$a,$now){$r=$reserve($tables[2]['table_id'],'No Show',0)['result']['reservation'];$call('transition',['reservation'=>$r['reservation_id'],'version'=>'1','status'=>'CONFIRMED']);denied(fn()=>$call('transition',['reservation'=>$r['reservation_id'],'version'=>'2','status'=>'NO_SHOW']));$later=new Seating($db,$pa,static fn()=>$now+1200);$later->act($a['merchant'],$a['outlet'],req(),'transition',['reservation'=>$r['reservation_id'],'version'=>'2','status'=>'NO_SHOW']);denied(fn()=>$call('floor',['id'=>$floors[0]['floor_id'],'version'=>'1','name'=>'Ground Floor','active'=>'0']));$t=$find('tables',$tables[2]['table_id']);$call('table',['id'=>$t['table_id'],'version'=>(string)$t['version'],'floor'=>$t['floor_id'],'name'=>$t['name'],'capacity'=>(string)$t['capacity'],'type'=>$t['table_type'],'active'=>'0','notes'=>'Retained']);check($find('reservations',$r['reservation_id'])['status']==='NO_SHOW');});
