test('Native staff owner manager cashier kitchen permissions and audit attribution',function()use($db,$a,$pa,$load,&$staff){$setup=new RestaurantSetup($db,$pa);foreach(['cashier','outlet_administrator','kitchen']as $role){$username='m05b-'.$role;$password='Synthetic-M05B-staff-password-123';$act=fn($op,$d)=>$setup->act($a['merchant'],$a['outlet'],(int)$setup->load($a['merchant'],$a['outlet'])['version'],req(),$op,$d);$new=$act('staff-create',['username'=>$username,'name'=>'Synthetic '.$role,'role'=>$role])['result'];$act('staff-activate',['user'=>$new['userId'],'password'=>$password,'confirmation'=>$password]);$p=principal($a,$username,$password);$s=new Seating($db,$p);if($role==='kitchen'){denied(fn()=>$s->load($a['merchant'],$a['outlet']));}else{$state=$s->load($a['merchant'],$a['outlet']);check($state['canConfigure']===($role==='outlet_administrator'));if($role==='cashier')denied(fn()=>$s->act($a['merchant'],$a['outlet'],req(),'floor',['id'=>'','version'=>'0','name'=>'Forbidden','active'=>'1']));else{$s->act($a['merchant'],$a['outlet'],req(),'floor',['id'=>'','version'=>'0','name'=>'Private Dining','active'=>'1']);check((bool)array_filter($s->load($a['merchant'],$a['outlet'])['events'],fn($e)=>$e['actor_id']===$new['userId']));}}$staff[$role]=['username'=>$username,'password'=>$password,'outlet'=>$a['loginOutlet'],'user'=>$new['userId']];}});
